CREATE TABLE IF NOT EXISTS intent_sessions_v10 (id BIGSERIAL PRIMARY KEY,traveler_id BIGINT REFERENCES traveler_profiles(id) ON DELETE SET NULL,country_id BIGINT REFERENCES countries(id) ON DELETE SET NULL,raw_text TEXT NOT NULL,intent JSONB NOT NULL DEFAULT '{}'::jsonb,missing_fields JSONB NOT NULL DEFAULT '[]'::jsonb,confidence NUMERIC(5,2) NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'qualified',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS traveler_request_matches_v10 (id BIGSERIAL PRIMARY KEY,request_id BIGINT REFERENCES traveler_requests_v9(id) ON DELETE CASCADE,professional_id BIGINT REFERENCES professional_profiles_v9(id) ON DELETE CASCADE,compatibility NUMERIC(5,2),distance_km NUMERIC(10,2),factors JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_intent_sessions_country ON intent_sessions_v10(country_id);CREATE INDEX IF NOT EXISTS idx_intent_sessions_status ON intent_sessions_v10(status);
